"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10779"],{17258(e){e.exports=JSON.parse('{"id":"FIN-1231","slug":"fiscal-multiplier","term":"Fiscal Multiplier","also_known_as":[],"difficulty":"Advanced","definition":"The fiscal multiplier is the ratio of the change in a country\'s GDP to the change in government spending or taxes that caused it.","explanation":["When a government spends more, the money becomes income for businesses and workers, who then spend part of it, creating further income for others. This chain of spending can make the total effect on GDP larger than the original spending.","For example, if a government spends an extra 10 billion and GDP rises by 15 billion as a result, the fiscal multiplier is 1.5. A multiplier below 1 means GDP rises by less than the spending, perhaps because the spending displaces private activity.","Multipliers vary with circumstances. They tend to be larger during recessions, when there are unemployed workers and idle resources, and when central banks keep interest rates low. They tend to be smaller when the economy is near full capacity, when spending leads to higher interest rates or when much of the extra demand goes on imports.","Tax cuts and spending increases may have different multipliers, and the size of multipliers is the subject of considerable debate among economists, since estimates differ widely."],"note":"","total":1500,"prev":{"slug":"fintech","term":"Fintech"},"next":{"slug":"fiscal-policy","term":"Fiscal Policy"}}')}}]);